const dir=load("reportDir");
const reads=await Promise.allSettled([
tools.exec_command({cmd:`cat '${dir}/summary.md'`,max_output_tokens:10000}),
tools.exec_command({cmd:`cat '${dir}/finding-index.json'`,max_output_tokens:6000})
]);
for (const r of reads) if(r.status!=="fulfilled" || r.value.exit_code!==0) throw new Error("Report verification read failed");
const summary=reads[0].value.output;
const index=JSON.parse(reads[1].value.output);
if(JSON.stringify(index)!==JSON.stringify(load("indexExpected"))) throw new Error("Index changed");
for(const f of index.findings) {
 if(!summary.includes(`### ${f.title}\n\n${f.quote}\n`)) throw new Error("Non-lossless finding quote");
}
text({verified_exact_quotes:index.findings.length,questions:index.questions.length,checkout:"clean; pinned HEAD and tree unchanged"});
